{"cards": [{"node_code": "N_e35f83950f93e401", "definition": "指桥梁工程施工过程中的组织规划、进度控制、资源配置、现场协调及安全管理等管理活动，旨在确保工程按既定目标高效实施。", "boundary": "本节点聚焦于“管理”与“组织”层面，而非具体技术工艺。边界在于区分“管理”与“技术”（具体施工方法归施工技术节点）、“管理”与“规范”（强制性标准与定额归规范与定额节点）。涵盖施工准备、过程控制、人员与机械调度等软性管理内容。", "includes": ["桥梁施工组织设计、进度计划与网络图分析", "施工现场管理、劳动力与材料调度、安全与质量管理", "施工成本控制、合同管理及工程协调机制"], "excludes": ["具体的桥梁结构施工工艺流程与技术细节", "国家或行业发布的施工技术标准、规范条文及定额指标"], "sibling_distinctions": [{"other_code": "N_c3987366fc9cf433", "rule": "区分依据为内容属性：本节点侧重“怎么管”（计划、协调、控制）；施工技术节点侧重“怎么做”（具体工艺、操作方法）。"}, {"other_code": "N_01dcd324716b2552", "rule": "区分依据为约束性质：本节点侧重项目内部的管理策略与执行；规范与定额节点侧重外部强制性标准、法规及资源消耗指标。"}], "cross_boundary_rule": "若内容涉及“基于BIM的施工管理”，侧重管理流程与数据应用归本节点，侧重BIM建模技术本身归相关技术节点或本节点技术部分。"}, {"node_code": "N_01dcd324716b2552", "definition": "指桥梁工程施工中必须遵循的技术标准、操作规程、质量验收规范，以及用于工程计价、资源消耗统计的劳动、材料和机械台班定额体系。", "boundary": "本节点聚焦于“标准”与“指标”。边界在于区分“规范”与“管理”（管理侧重执行策略，规范侧重合规要求）、“定额”与“造价”（定额是基础数据，造价是应用结果，若树中无独立造价节点，造价计算依据归此）。涵盖国标、行标、地标及企业标准中的施工部分。", "includes": ["桥梁施工技术规范、安全操作规程、质量检验与验收标准", "施工劳动定额、材料消耗定额、机械台班定额", "施工预算编制依据及工程量计算规则"], "excludes": ["具体的施工技术方案设计与工艺创新", "施工过程中的现场管理措施与进度控制方法"], "sibling_distinctions": [{"other_code": "N_e35f83950f93e401", "rule": "区分依据为功能：本节点提供“依据”（标准与数据）；施工组织与管理节点提供“方法”（如何应用依据进行计划与控制）。"}, {"other_code": "N_c3987366fc9cf433", "rule": "区分依据为性质：本节点为规范性、指标性内容；施工技术节点为操作性、工艺性内容。"}], "cross_boundary_rule": "若内容涉及“新规范对施工工法的影响”，侧重规范条文解读归本节点，侧重工法调整归施工技术节点。"}, {"node_code": "N_d7c4d01bcbcbc7bd", "definition": "指用于桥梁工程施工的各类机械设备、专用工具、起重吊装设备、混凝土生产设备及检测仪器，涵盖其选型、性能参数、操作维护及新技术应用。", "boundary": "本节点聚焦于“硬件”工具。边界在于区分“设备”与“技术”（设备侧重机器本身，技术侧重使用机器的工艺）、“设备”与“管理”（设备侧重物理属性，管理侧重调度与保养制度）。涵盖通用机械在桥梁施工中的专用化应用。", "includes": ["桥梁专用施工机械（如架桥机、造桥机、打桩机）的结构与性能", "通用施工机械（如挖掘机、起重机、混凝土泵车）在桥梁工程中的应用", "施工辅助工具、测量仪器及设备的维护保养技术"], "excludes": ["施工机械的调度计划与现场管理流程", "使用机械进行具体结构施工的工艺步骤与操作技巧"], "sibling_distinctions": [{"other_code": "N_c3987366fc9cf433", "rule": "区分依据为对象：本节点侧重“机器”（设备本体、参数、选型）；施工技术节点侧重“工艺”（如何用机器完成结构建造）。"}, {"other_code": "N_e35f83950f93e401", "rule": "区分依据为维度：本节点侧重物理工具；施工组织与管理节点侧重对工具及人员的组织调度。"}], "cross_boundary_rule": "若内容涉及“智能施工装备”，侧重装备硬件结构与控制系统归本节点，侧重装备在整体施工方案中的集成应用归施工组织与管理或施工技术节点。"}]}
